// Copies the third-party runtime files the flyer tool loads on demand into
// public/, so the site serves them itself (no outside CDN):
//  - onnxruntime-web -> public/ort/    (the "Enhance with AI" step, ~40 MB)
//  - pdf.js          -> public/pdfjs/  (reading PDF flyers, ~6 MB)
// They are build output (git-ignored), regenerated by the predev / prebuild
// hooks in package.json.
import { copyFileSync, cpSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const from = join(root, "node_modules", "onnxruntime-web", "dist");
const to = join(root, "public", "ort");

const files = [
  // WebGPU build (fast path) and the WebAssembly CPU build (fallback).
  "ort.webgpu.min.mjs",
  "ort-wasm-simd-threaded.asyncify.mjs",
  // ort-wasm-simd-threaded.asyncify.wasm is deliberately NOT copied: at
  // ~26.8 MB it's over Cloudflare Workers' 25 MiB static-asset limit, so it's
  // served from R2 instead (see NEXT_PUBLIC_ORT_ASYNCIFY_WASM_URL in
  // lib/flyer-print/enhance.ts).
  "ort.wasm.min.mjs",
  "ort-wasm-simd-threaded.mjs",
  "ort-wasm-simd-threaded.wasm",
];

mkdirSync(to, { recursive: true });
for (const file of files) {
  const source = join(from, file);
  if (!existsSync(source)) {
    console.error(`copy-ort-runtime: missing ${source} (is onnxruntime-web installed?)`);
    process.exit(1);
  }
  copyFileSync(source, join(to, file));
}
console.log(`copy-ort-runtime: copied ${files.length} files to public/ort`);

// pdf.js: the library, its worker, and the data folders it reads at runtime
// (fonts, Chinese character maps, image decoders, colour profiles).
const pdfFrom = join(root, "node_modules", "pdfjs-dist");
const pdfTo = join(root, "public", "pdfjs");
mkdirSync(pdfTo, { recursive: true });
for (const file of ["pdf.min.mjs", "pdf.worker.min.mjs"]) {
  const source = join(pdfFrom, "build", file);
  if (!existsSync(source)) {
    console.error(`copy-ort-runtime: missing ${source} (is pdfjs-dist installed?)`);
    process.exit(1);
  }
  copyFileSync(source, join(pdfTo, file));
}
for (const dir of ["cmaps", "standard_fonts", "wasm", "iccs"]) {
  cpSync(join(pdfFrom, dir), join(pdfTo, dir), { recursive: true });
}
console.log("copy-ort-runtime: copied pdf.js to public/pdfjs");
